        "groundingSupports": [
          {
            "segment": {
              "endIndex": 136,
              "text": "**Otters** are semiaquatic carnivorous mammals that belong to the mustelid family (which also includes weasels, badgers, and wolverines)"
            },
            "groundingChunkIndices": [
              0,
              1
            ]
          },
          {
            "segment": {
              "startIndex": 140,
              "endIndex": 333,
              "text": "Key facts:\n* **Species & Habitat:** There are 13 recognized species found worldwide (except in Australia and Antarctica), living in freshwater rivers, lakes, wetlands, and coastal marine waters"
            },
            "groundingChunkIndices": [
              2,
              3
            ]
          },
          {
            "segment": {
              "startIndex": 335,
              "endIndex": 438,
              "text": "* **Physical Traits:** They have streamlined bodies, webbed feet, and powerful tails built for swimming"
            },
            "groundingChunkIndices": [
              0,
              3
            ]
          },
          {
            "segment": {
              "startIndex": 440,
              "endIndex": 566,
              "text": "Instead of blubber, sea otters stay warm using the densest fur in the animal kingdom—up to one million hairs per square inch"
            },
            "groundingChunkIndices": [
              4,
              1
            ]
          },
          {
            "segment": {
              "startIndex": 568,
              "endIndex": 652,
              "text": "* **Diet:** Carnivorous, primarily feeding on fish, crabs, shellfish, and amphibians"
            },
            "groundingChunkIndices": [
              0,
              3
            ]
          },
          {
            "segment": {
              "startIndex": 654,
              "endIndex": 728,
              "text": "Some sea otters are known to use stones as tools to crack open hard shells"
            },
            "groundingChunkIndices": [
              0
            ]
          },
          {
            "segment": {
              "startIndex": 730,
              "endIndex": 870,
              "text": "* **Behavior:** Highly intelligent, social, and playful; they frequently slide down mud or snow banks and have a wide range of vocalizations"
            },
            "groundingChunkIndices": [
              0,
              5,
              1
            ]
          },
          {
            "segment": {
              "startIndex": 872,
              "endIndex": 971,
              "text": "When resting in water, sea otters often hold paws or wrap themselves in kelp to avoid drifting away"
            },
            "groundingChunkIndices": [
              6,
              1
            ]
          }
        ],
